package cn.lili.modules.community.p0.stage3;
import cn.lili.common.security.AuthUser;import cn.lili.modules.member.mapper.MerchantGrantMapper;import cn.lili.modules.community.p0.support.*;import org.junit.jupiter.api.Test;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class Stage3AuthorizationTest {
 static MerchantGrantMapper.Grant grant(String action,boolean write){var g=new MerchantGrantMapper.Grant();g.setPermission(action);g.setWriteGrant(write);g.setStoreId("3");return g;}
 @Test void oldSupplyGrantsDoNotBecomeFulfillmentAndCurrentGrantIsReadEveryTime(){var db=mock(Stage1Db.class);var grants=mock(MerchantGrantMapper.class);var user=new AuthUser();user.setId("1");user.setClerkId("2");user.setStoreId("3");when(db.required(anyString(),any(Object[].class))).thenReturn(map("shopkeeper",false,"department_id","4","status",true,"delete_flag",false,"revoked",false,"member_id","1"));var service=new Stage3Authorization(db,mock(Stage1Access.class),grants);
 when(grants.current("2","3","4")).thenReturn(List.of(grant("s1.stock.write",true),grant("s1.goods.write",true),grant("s3.fulfillment.write",false)));assertTrue(service.storePermissions(user).isEmpty());
 when(grants.current("2","3","4")).thenReturn(List.of(grant("s3.order.read",false),grant("s3.fulfillment.write",true)));assertEquals(Set.of("order.read","fulfillment.write"),service.storePermissions(user));
 when(grants.current("2","3","4")).thenReturn(List.of());assertTrue(service.storePermissions(user).isEmpty());verify(grants,times(3)).current("2","3","4");}
 @Test void revokedClerkAndWrongOwnerProofCannotOperateHistory(){var db=mock(Stage1Db.class);var grants=mock(MerchantGrantMapper.class);var user=new AuthUser();user.setId("1");user.setClerkId("2");user.setStoreId("3");var service=new Stage3Authorization(db,mock(Stage1Access.class),grants);when(db.required(anyString(),any(Object[].class))).thenReturn(map("shopkeeper",false,"status",true,"delete_flag",false,"revoked",true));assertThrows(Stage1Exception.class,()->service.storePermissions(user));when(db.required(anyString(),any(Object[].class))).thenReturn(map("shopkeeper",true,"status",true,"delete_flag",false,"revoked",false,"member_id","9"));assertThrows(Stage1Exception.class,()->service.storePermissions(user));verifyNoInteractions(grants);}
}
